local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local UserClashUpdateView = class("UserClashUpdateView", NewViewBaseLayer)
local CocosUtil = require("hall.util.CocosUtil")
local addNumber = require("hall.familyCircle.addNumber")

local EVENTNAME = {
	GET_CLIB_USER_INFO = "/getClubUserInfo",
	ADD_JOIN_GAME_LIMIT = "/addJoinGameLimit",
}

function UserClashUpdateView:ctor(data, clubId, key)

    dump(data, 'dataxxxxxxxxxxxxx')
    dump(clubId, 'dataxxxxxxxxxxxxx')
    dump(key, 'dataxxxxxxxxxxxxx')

    self._key = key
    local csbPath = "hall/res/FriendScircle/UserClashUpdateView.csb"
    UserClashUpdateView.super.ctor(self, csbPath)

    self._data = data or {}--右邊的數據
    self._clubId = clubId
    self:InitGame()

    self._seachData = {}--左邊的數據
    self._inputSearchUid = nil
    self._imgInputUid:onClick(handler(self, self.inputUid))
end

function UserClashUpdateView:inputUid()

    local addNumber = addNumber.new(handler(self, self.setUserId))
    self:addChild(addNumber)

end

function UserClashUpdateView:setUserId(callData)
    local number = callData.number or ""
    self._inputSearchUid = number
    self._txtSearchUid:setString(number)
end

function UserClashUpdateView:InitGame()
    local tempUserInfoAr = {}
    local tmpAr = {}
    for i, v in ipairs(self._data or {}) do
        if #tmpAr == 5 then
            table.insert(tempUserInfoAr, tmpAr)
            tmpAr = {}
        end
        table.insert(tmpAr, v)
        if i == #self._data then
            table.insert(tempUserInfoAr, tmpAr)
        end
    end
    dump(tempUserInfoAr, "tempUserInfoAr == ")
    self.selectUserLst:removeAllChildren()

    for i, v in ipairs(tempUserInfoAr) do
        local item = self.userInfosCell:clone()
        if item then
            self:infoItemForData(item, v, 2)
            self.selectUserLst:pushBackCustomItem(item)
        end
    end
end

function UserClashUpdateView:infoItemForData(obj, data, type)
    for i = 1, 5 do
        local tUser = obj:getChildByName("userNode"..i)
        if tUser then
            tUser:setVisible(false)
        end
    end

    for i, v in ipairs(data or {}) do
        local tUser = obj:getChildByName("userNode"..i)
        if tUser then
            tUser:setVisible(true)
            self:initUserInfoAndListen(tUser, v, type) --2表示右邊的
        end
    end
end

function UserClashUpdateView:seachUserCb(msgData)
    dump(msgData, 'msgData----------------')
    local netData = json.decode(msgData.netData)
    local returnCode = tonumber(netData.returnCode)
    local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end

    --self:initClashData(data or {})
    for i,v in ipairs(self._seachData) do
        if v.uid == data.uid then
            return
        end
    end

    for i, v in ipairs(self._data) do
        if v.uid == data.uid then
            return
        end
    end
    print("seachUserCb--------------")
    self:addUserToSeachLst(data)
end

function UserClashUpdateView:addUserToSeachLst(data)
    dump(self._seachData, "self._seachData == ")
    local surp = math.fmod(#self._seachData, 5)
    print("addUserToSeachLst ------------", surp)
    if surp == 0 then
        local index = math.modf(#self._seachData/5) + 1
        local tmpAr = {}
        table.insert(tmpAr, data)
        local item = self.userInfosCell:clone()
        if item then
            table.insert(self._seachData, data)
            self:infoItemForData(item, tmpAr, 1)
            self._listSearchUsers:pushBackCustomItem(item)
        end
    else
        local index = math.floor(#self._seachData/5) + 1
        local item = self._listSearchUsers:getItem(index - 1)
        if item then
            local tUser = item:getChildByName("userNode"..(surp+1))
            if tUser then
                table.insert(self._seachData, data)
                tUser:setVisible(true)
                self:initUserInfoAndListen(tUser, data, 1) --2表示右邊的
            end
        end
    end
end

function UserClashUpdateView:addUserToGroupArLst(data)
    local surp = math.fmod(#self._data, 5)
    if surp == 0 then
        local index = math.modf(#self._data/5) + 1
        local tmpAr = {}
        table.insert(tmpAr, data)
        local item = self.userInfosCell:clone()
        if item then
            table.insert(self._data, data)
            self:infoItemForData(item, tmpAr, 2)
            self.selectUserLst:pushBackCustomItem(item)
        end
    else
        local index = math.floor(#self._data/5) + 1
        local item = self.selectUserLst:getItem(index - 1)
        if item then
            local tUser = item:getChildByName("userNode"..(surp + 1))
            if tUser then
                table.insert(self._data, data)
                tUser:setVisible(true)
                self:initUserInfoAndListen(tUser, data, 2) --2表示右邊的
            end
        end
    end
end

function UserClashUpdateView:removeLeftUser(data)

    for i,v in ipairs(self._seachData) do
        if data.uid == v.uid then
            table.remove(self._seachData, i)
            break
        end
    end

    local tempUserInfoAr = {}
    local tmpAr = {}
    for i, v in ipairs(self._seachData or {}) do
        if #tmpAr == 5 then
            table.insert(tempUserInfoAr, tmpAr)
            tmpAr = {}
        end
        table.insert(tmpAr, v)
        if i == #self._seachData then
            table.insert(tempUserInfoAr, tmpAr)
        end
    end
    dump(self._seachData, "self._seachData == ")
    dump(tempUserInfoAr, "removeLeftUser == ")
    self._listSearchUsers:removeAllChildren()
    for i, v in ipairs(tempUserInfoAr) do
        local item = self.userInfosCell:clone()
        if item then
            self:infoItemForData(item, v, 1)
            self._listSearchUsers:pushBackCustomItem(item)
        end
    end
end

function UserClashUpdateView:removeRightUser(data)
    for i,v in ipairs(self._data) do
        if data.uid == v.uid then
            table.remove(self._data, i)
            break
        end
    end
    self:InitGame()
end

function UserClashUpdateView:initUserInfoAndListen(eachUser, data, type)
    local uid = eachUser:getChildByName("uId")
    if uid then
        uid:setString(data.uid or "0")
    end
    local name = eachUser:getChildByName("name")
    if name then
        name:setString(data.nickName or "0")
    end

    local headImg = eachUser:getChildByName("headImg")
    
    if headImg then
        require("hall.GameCommon"):getUserHead(data.smallIcon, nil, nil, headImg, 66)
        
    end

    local btnClickHead = eachUser:getChildByName("btnClickHead")
    if btnClickHead then
        btnClickHead._userData = data
        btnClickHead._userType = type
        btnClickHead:addTouchEventListener(handler(self, self.onClickUser))
    end
end

function UserClashUpdateView:onClickUser(sender, event)
    print("onClickUser -------------", sender._userType)
    if event == TOUCH_EVENT_ENDED then
        local type = sender._userType
        if type == 1 then
            if #self._data >= 11 then
                viewMgr:showTip({text = '每组最多11人'})
            else
                self:removeLeftUser(sender._userData)
                self:addUserToGroupArLst(sender._userData)
            end
        else
            self:removeRightUser(sender._userData)
            self:addUserToSeachLst(sender._userData)
        end
    end
end

function UserClashUpdateView:onClickBtnSearch()

    if self._inputSearchUid == nil or self._inputSearchUid == '' then
        viewMgr:showTip({text = '请输入有效的ID'})
        return
    end

    local input = self._inputSearchUid
    if tonumber(input) then
        self:seachUserById(input)
    end
end

function UserClashUpdateView:onClickBtnSure()
    
    local uidAr = {}
    for i, v in ipairs(self._data) do
        table.insert(uidAr, v.uid)
    end
    local groupStr = table.concat(uidAr, "-")
    self:sendUpdateGroupInfo(groupStr)
end

function UserClashUpdateView:seachUserById(uId)
    local this = self
    local interfaceName = EVENTNAME.GET_CLIB_USER_INFO
    local httpType = "POST"

     local data = {
            groupId = self._clubId,
            searchId = uId,
     }
    local function callback(returnCode, data)
     
    end

    cct.createHttRq({
        url = HttpAddr .. interfaceName,
        date = data,
        type_= httpType,

        callBack = handler(this, this.seachUserCb)})
end

function UserClashUpdateView:sendUpdateGroupInfo(groupStr)
    local this = self
    local interfaceName = EVENTNAME.ADD_JOIN_GAME_LIMIT
    local httpType = "POST"

    local data = {}
    if self._key then
        data = {
            groupId = self._clubId,
            addUser = groupStr,
            key = self._key
        }
    else
        data = {
            groupId = self._clubId,
            addUser = groupStr
        }
    end

    dump(data,'requestPara------------')
    cct.createHttRq({
        url = HttpAddr .. interfaceName,
        date = data,
        type_= httpType,

        callBack = function(data)
            local returnCode = tonumber(json.decode(data.netData).returnCode)
            if 0 == returnCode then 
                viewMgr:showTip({text = "添加成功"})
                self:getParent():InitGame()
                self:removeSelf()
            elseif 1 == returnCode then 
                local data = json.decode(data.netData)
                local error = data.error
                viewMgr:showTip({text = error})
                return
            end 
        end})
end

function UserClashUpdateView:onClickBtnReturn()
    self:removeSelf()
end

function UserClashUpdateView:onExit()
end


return UserClashUpdateView